insert into terms (slug, name, part_of_speech, short_definition, full_definition, guide_title, guide, related) values
  ('soft-boil', 'Soft-boil', 'verb', 'Cook an egg in its shell just long enough for the white to set while the yolk stays runny. Usually 5 to 7 minutes in boiling water.', 'Cooking an egg in its shell for a short time, so the white turns firm but the yolk stays runny. It is a hard-boiled egg that you take out early on purpose.', 'Timing guide, large egg from the fridge', '[{"label":"4 min","result":"Very runny yolk, soft white"},{"label":"6 min","result":"Runny yolk, set white"},{"label":"8 min","result":"Jammy, mostly set yolk"},{"label":"10+ min","result":"Hard-boiled, firm yolk"}]'::jsonb, '{rolling-boil}'),
  ('rolling-boil', 'Rolling boil', 'noun', 'Big bubbles that keep breaking the surface, even when you stir. Hotter and more vigorous than a simmer.', 'Water heated until large bubbles rise and break the surface constantly, and stirring does not stop them. Use it when a recipe needs the water as hot as it gets.', null, null, '{simmer,soft-boil}'),
  ('simmer', 'Simmer', 'verb', 'Cook in liquid with small, gentle bubbles just breaking the surface. Lower heat than a boil.', 'Keeping a liquid just below boiling, with a few small bubbles rising now and then. It cooks food gently so it stays tender and sauces do not burn.', null, null, '{rolling-boil}'),
  ('whisk', 'Whisk', 'verb', 'Beat quickly with a whisk or fork until fully mixed and a little frothy.', 'Stirring fast in small circles with a whisk or fork to blend ingredients and add a little air. For eggs, whisk until no streaks of white are left.', null, null, '{}'),
  ('golden', 'Golden', 'adjective', 'Cooked until light brown on the outside, like toast. Not dark brown.', 'The light brown color food turns when it is fried or toasted. It means the outside is crisp and cooked, but it has not started to burn.', null, null, '{}');
